using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;using KianaPet;
class ShuffleRequestTests {
 static int checks;static readonly List<string> names=new List<string>();
 static void Check(bool value,string name){if(!value)throw new Exception(name);checks++;names.Add(name);}
 static object F(object obj,string key){return obj.GetType().GetField(key,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(obj);}
 static void Set(object obj,string key,object value){obj.GetType().GetField(key,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(obj,value);}
 static object Call(object obj,string key,params object[] args){return obj.GetType().GetMethod(key,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(obj,args);}
 [STAThread]static int Main(string[] args){Store.Root=args[0];Store.Save(new Config{LinkChatGPT=false,MusicEnabled=false,Walking=false,Gravity=false,AmbientActions=false,SleepSchedule=false,IdleSleep=false,HideFullscreen=false,LaunchChatGPTOnStart=false,LaunchMusicOnStart=false,NoticeSound=false});var app=new Application{ShutdownMode=ShutdownMode.OnLastWindowClose};var pet=new PetWindow(true);bool passed=false;
  pet.Loaded+=async delegate{try{
   await Task.Delay(1100);((DispatcherTimer)F(pet,"animation")).Stop();var window=app.Windows.OfType<SettingsWindow>().Single();window.NavigateCategory("外观与互动","随机换装");await Task.Delay(80);window.UpdateStatus();var nowButton=(Button)F(window,"skinShuffleNow");var cancel=(Button)F(window,"skinShuffleCancel");Check(nowButton.IsVisible&&nowButton.IsEnabled&&!cancel.IsEnabled,"one-shot button visible and ready in random outfit settings");string original=pet.Settings.Skin;var planner=(SkinShufflePlanner)F(pet,"skinShuffle");double remaining=planner.Session.Remaining;string bag=Store.Json.Serialize(planner.Session.Bag);
   nowButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(pet.SkinShuffleRequested&&!nowButton.IsEnabled&&cancel.IsEnabled,"button queues exactly one request and offers cancellation");Check(pet.Settings.Skin==original&&planner.Session.Remaining==remaining&&Store.Json.Serialize(planner.Session.Bag)==bag,"click does not immediately change outfit, timer or shuffled round");Check(pet.SkinShuffleStatus.Contains("排队")&&pet.SkinShuffleStatus.Contains("衔接"),"queued request explains boundary waiting with settings open");pet.RequestSkinShuffle();Check(planner.Session.Remaining==remaining&&pet.SkinShuffleRequested,"repeated request does not reset the timer or create a second request");double now=((System.Diagnostics.Stopwatch)F(pet,"clock")).Elapsed.TotalSeconds;Check(!(bool)Call(pet,"ExecuteSkinShuffle",now,false)&&pet.SkinShuffleRequested,"open settings do not bypass the animation boundary");window.Capture(Path.Combine(Store.Root,"immediate-skin-request.png"));cancel.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(!pet.SkinShuffleRequested&&nowButton.IsEnabled&&!cancel.IsEnabled,"cancel clears only the one-shot request");Check(planner.Session.Remaining==remaining,"cancel leaves normal countdown untouched");
   foreach(var pair in (Dictionary<string,CheckBox>)F(window,"skinShuffleChoices"))pair.Value.IsChecked=false;window.UpdateStatus();Check(!nowButton.IsEnabled&&!pet.SkinShuffleRequested,"empty candidate pool disables the button");pet.RequestSkinShuffle();Check(!pet.SkinShuffleRequested&&pet.SkinShuffleStatus.Contains("未选择"),"direct request with no candidates explains why it was rejected");SettingsWindow.Descendants<Button>(window).Single(b=>(string)b.Content=="只选三套 Q 版").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));window.Close();pet.IsHitTestVisible=false;Set(pet,"hover",false);Set(pet,"interaction",null);Set(pet,"state","idle");Set(pet,"quietActive",false);Set(pet,"menuLayerYielding",false);Set(pet,"displayPending",false);Set(pet,"sleeping",false);
   pet.RequestSkinShuffle();foreach(var field in new[]{"pressed","dragging","sleeping","quietActive","sessionLocked","manualHidden","menuLayerYielding"}){Set(pet,field,true);Check(!(bool)Call(pet,"ExecuteSkinShuffle",now,true)&&pet.SkinShuffleRequested,"one-shot respects protection: "+field);Set(pet,field,false);}pet.StartFocus(false);Check(!(bool)Call(pet,"ExecuteSkinShuffle",now,true),"focus blocks one-shot execution");pet.ResetFocus();pet.Settings.LinkChatGPT=true;pet.Link.Current.Connected=true;pet.Link.Current.State="running";pet.Link.Current.At=DateTime.UtcNow;Check(!(bool)Call(pet,"ExecuteSkinShuffle",now,true)&&pet.SkinShuffleStatus.Contains("GPT"),"live GPT task blocks and explains one-shot waiting");pet.Settings.LinkChatGPT=false;pet.Link.Current.Connected=false;pet.Link.Current.State="idle";
   pet.Settings.SkinShuffleEnabled=false;pet.Settings.SkinShuffleOnStart=false;pet.UpdateSkinShuffleSettings();pet.HoldSkinToday();pet.RequestSkinShuffle();Check(pet.SkinShuffleRequested&&planner.Held(DateTime.Now)&&!pet.Settings.SkinShuffleEnabled,"explicit request works with automatic modes off and retains today hold");Check(!(bool)Call(pet,"ExecuteSkinShuffle",now,false)&&pet.SkinShuffleRequested,"safe state alone cannot bypass animation boundary");
   pet.Settings.MusicEnabled=true;pet.Settings.MusicChorusEnabled=false;pet.Music.Current=new MusicState{Connected=true,Playing=true,Id="123",HasPosition=false,At=DateTime.UtcNow};Set(pet,"state","music-quiet");Set(pet,"stateAt",now-20);Set(pet,"drawnMusicState","music-quiet");Set(pet,"musicRising",false);Call(pet,"ChooseMusicReaction",now-10,true);Call(pet,"ChooseMusicReaction",now,true);Call(pet,"DrawAnimation",20000d);var session=F(pet,"musicReactionPlanner");var started=F(session,"started");var entered=F(session,"enteredAt");var poll=((DispatcherTimer)F(pet,"poll")).Interval;var musicPoll=((DispatcherTimer)F(pet,"musicTimer")).Interval;double at=(double)F(pet,"stateAt"),width=pet.Width,height=pet.Height;
   pet.Music.Current.HasPosition=true;pet.Music.Current.Position=20;pet.Settings.MusicSongPreferences=new[]{new SongMusicPreference{Id="123",Start=0,End=60}};Check(!(bool)Call(pet,"ExecuteSkinShuffle",now,true)&&pet.SkinShuffleRequested,"known chorus still blocks explicit randomization");pet.Music.Current.HasPosition=false;pet.Settings.MusicSongPreferences=new SongMusicPreference[0];
   Check((bool)Call(pet,"ExecuteSkinShuffle",now,true)&&pet.Settings.Skin!=original&&!pet.SkinShuffleRequested,"one-shot changes to a selected different outfit at the safe boundary");Check(pet.CurrentAction=="music-quiet"&&(double)F(pet,"stateAt")==at&&F(pet,"interaction")==null&&pet.Width==width&&pet.Height==height,"one-shot preserves pose timeline, dimensions and silent behavior");Check(ReferenceEquals(session,F(pet,"musicReactionPlanner"))&&Equals(started,F(session,"started"))&&Equals(entered,F(session,"enteredAt"))&&poll==((DispatcherTimer)F(pet,"poll")).Interval&&musicPoll==((DispatcherTimer)F(pet,"musicTimer")).Interval,"one-shot preserves music session and connection polling");Check(planner.Held(DateTime.Now)&&!pet.Settings.SkinShuffleEnabled&&!pet.Settings.SkinShuffleOnStart,"one-shot does not alter automatic switches or today hold");string changed=pet.Settings.Skin;Check(!(bool)Call(pet,"ExecuteSkinShuffle",now+1,true)&&pet.Settings.Skin==changed,"completed one-shot cannot execute twice");
   pet.RequestSkinShuffle();pet.SelectSkin(original);Check(!pet.SkinShuffleRequested,"manual outfit selection cancels older queued request");pet.RequestSkinShuffle();pet.UpdateSkinShuffleSettings();Check(!pet.SkinShuffleRequested,"editing random configuration cancels queued request");pet.RequestSkinShuffle();pet.HoldSkinToday();Check(!pet.SkinShuffleRequested,"holding today's outfit cancels queued request");pet.RequestSkinShuffle();pet.ResumeSkinShuffle();Check(!pet.SkinShuffleRequested,"resetting rotation cancels queued request");
   pet.Settings.SkinShufflePool=new[]{pet.Settings.Skin};pet.UpdateSkinShuffleSettings();pet.RequestSkinShuffle();Check(!pet.SkinShuffleRequested&&pet.SkinShuffleStatus.Contains("唯一"),"single current candidate never queues a no-op");
   string bad="kiana-winter-wish",asset=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"assets",bad+".png"),backup=asset+".test-backup";Check(Path.GetFullPath(asset).Contains(Path.Combine(".local","tests")),"failure fixture only changes isolated assets");pet.Settings.SkinShufflePool=new[]{bad};pet.UpdateSkinShuffleSettings();Set(pet,"interaction",null);Set(pet,"state","idle");pet.Settings.MusicEnabled=false;pet.RequestSkinShuffle();string old=pet.Settings.Skin;File.Move(asset,backup);try{Check(!(bool)Call(pet,"ExecuteSkinShuffle",now,true)&&!pet.SkinShuffleRequested&&pet.Settings.Skin==old,"failed one-shot restores outfit and consumes request");Check(!(bool)Call(pet,"ExecuteSkinShuffle",now+1,true)&&pet.SkinShuffleStatus.Contains("未完成"),"failed one-shot does not retry forever");}finally{File.Move(backup,asset);}pet.Settings.SkinShufflePool=SkinShuffleRules.Defaults.ToArray();pet.UpdateSkinShuffleSettings();pet.RequestSkinShuffle();string serialized=Store.Json.Serialize(planner.Session);var restored=new SkinShufflePlanner(new Random(2));restored.Load(Store.Json.Deserialize<SkinShuffleSession>(serialized),pet.Settings);Check(!restored.Due(pet.Settings,DateTime.Now)&&!serialized.Contains("Requested"),"one-shot is not persisted or replayed on restart");pet.CancelSkinShuffleRequest();passed=true;
  }catch(Exception e){Store.Atomic("error.json",new{error=e.ToString(),checks});}finally{Store.Atomic("result.json",new{passed,checks,names});foreach(var w in app.Windows.Cast<Window>().Where(w=>w!=pet).ToArray())w.Close();pet.Close();}};app.Run(pet);return passed?0:1;
 }
}
